#include "WebServerManager.h"
#include <ETH.h>
#include <SD.h>
#include "../core/ConfigManager.h"
#include "../core/Statistics.h"
#include "../storage/SDCardManager.h"
#include "../services/ReminderManager.h"
#include "../services/TimeManager.h"
#include "TelegramManager.h"

WebServerManager webServerManager;

static String esc(String v){v.replace("&","&amp;");v.replace("<","&lt;");v.replace(">","&gt;");v.replace("\"","&quot;");v.replace("'","&#39;");return v;}
static String p2(int v){return v<10?"0"+String(v):String(v);}
static const char* typeValue(ReminderType t){switch(t){case ReminderType::DAILY:return "daily";case ReminderType::WEEKLY:return "weekly";case ReminderType::MONTHLY:return "monthly";case ReminderType::YEARLY:return "yearly";default:return "once";}}
static String scheduleText(const Reminder&r){static const char* d[]={"Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"};if(r.type==ReminderType::ONCE)return "Once: "+p2(r.day)+"."+p2(r.month)+"."+String(r.year);if(r.type==ReminderType::DAILY)return "Every day";if(r.type==ReminderType::WEEKLY)return r.weekday>=0&&r.weekday<7?String("Every ")+d[r.weekday]:"Every week";if(r.type==ReminderType::MONTHLY)return "Every month on day "+String(r.day);return "Every year on "+p2(r.day)+"."+p2(r.month);}

static bool readReminder(WebServer&s,Reminder&r,bool edit){String msg=s.arg("message"),chat=s.arg("chatId"),type=s.arg("type"),tm=s.arg("time");msg.trim();chat.trim();if(!msg.length()||!config.hasChat(chat)||tm.length()!=5)return false;r.message=msg;r.chatId=chat;r.silent=s.hasArg("silent");r.enabled=!edit||s.hasArg("enabled");r.hour=tm.substring(0,2).toInt();r.minute=tm.substring(3,5).toInt();if(r.hour<0||r.hour>23||r.minute<0||r.minute>59)return false;if(type=="daily")r.type=ReminderType::DAILY;else if(type=="weekly")r.type=ReminderType::WEEKLY;else if(type=="monthly")r.type=ReminderType::MONTHLY;else if(type=="yearly")r.type=ReminderType::YEARLY;else r.type=ReminderType::ONCE;if(r.type==ReminderType::ONCE){String d=s.arg("onceDate");if(d.length()!=10)return false;r.year=d.substring(0,4).toInt();r.month=d.substring(5,7).toInt();r.day=d.substring(8,10).toInt();return r.year>=2000&&r.month>=1&&r.month<=12&&r.day>=1&&r.day<=31;}if(r.type==ReminderType::WEEKLY){r.weekday=s.arg("weekday").toInt();return r.weekday>=0&&r.weekday<=6;}if(r.type==ReminderType::MONTHLY){r.day=s.arg("monthlyDay").toInt();return r.day>=1&&r.day<=31;}if(r.type==ReminderType::YEARLY){r.day=s.arg("yearlyDay").toInt();r.month=s.arg("yearlyMonth").toInt();return r.day>=1&&r.day<=31&&r.month>=1&&r.month<=12;}return true;}

void WebServerManager::begin(){server.on("/",HTTP_GET,[this](){handleRoot();});server.on("/settings",HTTP_GET,[this](){handleSettings();});server.on("/settings/save",HTTP_POST,[this](){handleSaveSettings();});server.on("/settings/chat/add",HTTP_POST,[this](){handleAddChat();});server.on("/settings/chat/edit",HTTP_GET,[this](){handleEditChat();});server.on("/settings/chat/edit",HTTP_POST,[this](){handleUpdateChat();});server.on("/settings/chat/delete",HTTP_POST,[this](){handleDeleteChat();});server.on("/reminders",HTTP_GET,[this](){handleReminders();});server.on("/reminders/add",HTTP_POST,[this](){handleAddReminder();});server.on("/reminders/edit",HTTP_GET,[this](){handleEditReminder();});server.on("/reminders/edit",HTTP_POST,[this](){handleUpdateReminder();});server.on("/reminders/clone",HTTP_POST,[this](){handleCloneReminder();});server.on("/reminders/delete",HTTP_POST,[this](){handleDeleteReminder();});server.on("/reminders/toggle",HTTP_POST,[this](){handleToggleReminder();});server.on("/api/telegram/send",HTTP_POST,[this](){handleHubTelegramSend();});server.onNotFound([this](){handleNotFound();});server.begin();Serial.printf("[WEB] Started: http://%s\n",ETH.localIP().toString().c_str());}
void WebServerManager::update(){server.handleClient();}

void WebServerManager::handleRoot(){String h=getPageHeader(config.getDeviceName())+getNavigation()+"<h1>"+esc(config.getDeviceName())+"</h1>";h+="<div class='card'><h2>Network</h2><p><b>Status:</b> "+String(ETH.linkUp()?"Online":"Offline")+"</p><p><b>IP:</b> "+ETH.localIP().toString()+"</p><p><b>Gateway:</b> "+ETH.gatewayIP().toString()+"</p><p><b>Speed:</b> "+String(ETH.linkSpeed())+" Mbps</p><p><b>Duplex:</b> "+String(ETH.fullDuplex()?"Full":"Half")+"</p></div>";h+="<div class='card'><h2>System</h2><p><b>Time:</b> "+timeManager.getDateTimeString()+"</p><p><b>Total uptime:</b> "+statistics.getTotalUptimeString()+"</p><p><b>Current session:</b> "+statistics.getCurrentUptimeString()+"</p><p><b>Boot count:</b> "+String(statistics.getBootCount())+"</p><p><b>Total errors:</b> "+String(statistics.getErrors())+"</p></div>";h+="<div class='card'><h2>Telegram</h2><p><b>Chats:</b> "+String(config.getChatCount())+"</p><p><b>Messages received:</b> "+String(statistics.getMessagesReceived())+"</p><p><b>Messages sent:</b> "+String(statistics.getMessagesSent())+"</p></div>";h+="<div class='card'><h2>Commands</h2><p><b>Received:</b> "+String(statistics.getCommandsReceived())+"</p><p><b>Executed:</b> "+String(statistics.getCommandsExecuted())+"</p><p><b>Errors:</b> "+String(statistics.getCommandErrors())+"</p></div>";h+="<div class='card'><h2>Storage</h2>";if(sdCard.isAvailable()){uint64_t t=SD.totalBytes(),u=SD.usedBytes();h+="<p><b>SD total:</b> "+String((double)t/1048576.0,2)+" MB</p><p><b>Used:</b> "+String((double)u/1048576.0,2)+" MB</p><p><b>Free:</b> "+String((double)(t-u)/1048576.0,2)+" MB</p>";}else h+="<p class='error'>SD card unavailable</p>";server.send(200,"text/html; charset=utf-8",h+"</div>"+getPageFooter());}

void WebServerManager::handleSettings(){String h=getPageHeader("Settings")+getNavigation()+"<h1>Settings</h1><form method='POST' action='/settings/save'>";h+="<div class='card'><h2>System</h2><label>Device name</label><input name='deviceName' value='"+esc(config.getDeviceName())+"'><label>Timezone</label><input name='timezone' value='"+esc(config.getTimezone())+"'><label>NTP server</label><input name='ntpServer' value='"+esc(config.getNtpServer())+"'></div>";h+="<div class='card'><h2>API and tokens</h2><label>Telegram bot token</label><input type='password' name='botToken' value='"+esc(config.getBotToken())+"'><label>Hub API key</label><input type='password' name='hubApiKey' value='"+esc(config.getHubApiKey())+"'></div>";h+="<div class='card'><h2>Startup message</h2><label class='checkbox'><input type='checkbox' name='startupMessageEnabled' "+String(config.isStartupMessageEnabled()?"checked":"")+"> Send after startup</label><label>Message</label><textarea name='startupMessage' rows='4'>"+esc(config.getStartupMessage())+"</textarea></div>";h+="<div class='card'><h2>GPIO Monitor</h2><h3>GPIO 35</h3><label class='checkbox'><input type='checkbox' name='gpio35Enabled' "+String(config.isGpio35Enabled()?"checked":"")+"> Enable</label><label>Message HIGH</label><input name='gpio35HighMessage' value='"+esc(config.getGpio35HighMessage())+"'><label>Message LOW</label><input name='gpio35LowMessage' value='"+esc(config.getGpio35LowMessage())+"'><h3>GPIO 39</h3><label class='checkbox'><input type='checkbox' name='gpio39Enabled' "+String(config.isGpio39Enabled()?"checked":"")+"> Enable</label><label>Message HIGH</label><input name='gpio39HighMessage' value='"+esc(config.getGpio39HighMessage())+"'><label>Message LOW</label><input name='gpio39LowMessage' value='"+esc(config.getGpio39LowMessage())+"'></div><button>Save settings</button></form>";h+="<div class='card'><h2>Telegram chats</h2>";for(size_t i=0;i<config.getChatCount();i++){auto c=config.getChat(i);h+="<div class='item'><b>"+esc(c.name)+"</b><br><code>"+esc(c.id)+"</code><div class='actions'><a class='button' href='/settings/chat/edit?index="+String(i)+"'>Edit</a><form method='POST' action='/settings/chat/delete'><input type='hidden' name='index' value='"+String(i)+"'><button class='danger' onclick='return confirm(\"Delete this chat?\")'>Delete</button></form></div></div>";}h+="<h3>Add chat</h3><form method='POST' action='/settings/chat/add'><label>Chat name</label><input name='name' required><label>Chat ID</label><input name='id' required><button>Add chat</button></form></div>";server.send(200,"text/html; charset=utf-8",h+getPageFooter());}

void WebServerManager::handleSaveSettings(){config.setDeviceName(server.arg("deviceName"));config.setTimezone(server.arg("timezone"));config.setNtpServer(server.arg("ntpServer"));config.setBotToken(server.arg("botToken"));config.setHubApiKey(server.arg("hubApiKey"));config.setStartupMessageEnabled(server.hasArg("startupMessageEnabled"));config.setStartupMessage(server.arg("startupMessage"));config.setGpio35Enabled(server.hasArg("gpio35Enabled"));config.setGpio35HighMessage(server.arg("gpio35HighMessage"));config.setGpio35LowMessage(server.arg("gpio35LowMessage"));config.setGpio39Enabled(server.hasArg("gpio39Enabled"));config.setGpio39HighMessage(server.arg("gpio39HighMessage"));config.setGpio39LowMessage(server.arg("gpio39LowMessage"));if(!config.save()){server.send(500,"text/plain","Save failed");return;}server.sendHeader("Location","/settings");server.send(303);}
void WebServerManager::handleAddChat(){String id=server.arg("id"),name=server.arg("name");id.trim();name.trim();if(!id.length()||!name.length()||!config.addChat(id,name)||!config.save()){server.send(400,"text/plain","Failed to add chat");return;}server.sendHeader("Location","/settings");server.send(303);}
void WebServerManager::handleEditChat(){size_t i=(size_t)server.arg("index").toInt();if(i>=config.getChatCount()){server.send(404,"text/plain","Chat not found");return;}auto c=config.getChat(i);String h=getPageHeader("Edit chat")+getNavigation()+"<h1>Edit chat</h1><div class='card'><form method='POST' action='/settings/chat/edit'><input type='hidden' name='index' value='"+String(i)+"'><label>Chat name</label><input name='name' value='"+esc(c.name)+"' required><label>Chat ID</label><input name='id' value='"+esc(c.id)+"' required><button>Save chat</button> <a class='button secondary' href='/settings'>Cancel</a></form></div>";server.send(200,"text/html; charset=utf-8",h+getPageFooter());}
void WebServerManager::handleUpdateChat(){size_t i=(size_t)server.arg("index").toInt();String id=server.arg("id"),name=server.arg("name");id.trim();name.trim();if(!id.length()||!name.length()||i>=config.getChatCount()||!config.updateChat(i,id,name)||!config.save()){server.send(400,"text/plain","Failed to update chat");return;}server.sendHeader("Location","/settings");server.send(303);}
void WebServerManager::handleDeleteChat(){size_t i=(size_t)server.arg("index").toInt();if(!config.deleteChat(i)||!config.save()){server.send(400,"text/plain","Failed to delete chat");return;}server.sendHeader("Location","/settings");server.send(303);}

static String reminderForm(const Reminder&r,bool edit){String h;if(edit)h+="<input type='hidden' name='id' value='"+String(r.id)+"'>";h+="<label>Message</label><textarea name='message' required>"+esc(r.message)+"</textarea><label>Chat</label><select name='chatId'>";for(size_t i=0;i<config.getChatCount();i++){auto c=config.getChat(i);h+="<option value='"+esc(c.id)+"' "+String(c.id==r.chatId?"selected":"")+">"+esc(c.name)+"</option>";}String tv=typeValue(r.type);h+="</select><label>Repeat</label><select name='type' id='type' onchange='updateFields()'>";const char* v[]={"once","daily","weekly","monthly","yearly"};const char* l[]={"Once","Every day","Every week","Every month","Every year"};for(int i=0;i<5;i++)h+="<option value='"+String(v[i])+"' "+String(tv==v[i]?"selected":"")+">"+l[i]+"</option>";h+="</select><div id='onceFields'><label>Date</label><input type='date' name='onceDate' value='"+String(r.year)+"-"+p2(r.month)+"-"+p2(r.day)+"'></div><div id='weeklyFields'><label>Weekday</label><select name='weekday'>";const char* wd[]={"Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"};for(int i=0;i<7;i++)h+="<option value='"+String(i)+"' "+String(r.weekday==i?"selected":"")+">"+wd[i]+"</option>";h+="</select></div><div id='monthlyFields'><label>Day</label><input type='number' name='monthlyDay' min='1' max='31' value='"+String(r.day?r.day:1)+"'></div><div id='yearlyFields'><label>Day</label><input type='number' name='yearlyDay' min='1' max='31' value='"+String(r.day?r.day:1)+"'><label>Month</label><input type='number' name='yearlyMonth' min='1' max='12' value='"+String(r.month?r.month:1)+"'></div><label>Time</label><input type='time' name='time' value='"+p2(r.hour)+":"+p2(r.minute)+"' required>";if(edit)h+="<label class='checkbox'><input type='checkbox' name='enabled' "+String(r.enabled?"checked":"")+"> Enabled</label>";h+="<label class='checkbox'><input type='checkbox' name='silent' "+String(r.silent?"checked":"")+"> Send without sound</label><script>function updateFields(){let t=document.getElementById('type').value;document.getElementById('onceFields').style.display=t==='once'?'block':'none';document.getElementById('weeklyFields').style.display=t==='weekly'?'block':'none';document.getElementById('monthlyFields').style.display=t==='monthly'?'block':'none';document.getElementById('yearlyFields').style.display=t==='yearly'?'block':'none'}updateFields()</script>";return h;}

void WebServerManager::handleReminders(){const size_t pp=20,total=reminderManager.getCount();size_t pages=(total+pp-1)/pp;if(!pages)pages=1;size_t page=server.hasArg("page")?(size_t)server.arg("page").toInt():1;if(page<1)page=1;if(page>pages)page=pages;size_t first=(page-1)*pp,last=first+pp;if(last>total)last=total;String h=getPageHeader("Reminders")+getNavigation()+"<h1>Reminders</h1><div class='card'><h2>My reminders ("+String(total)+")</h2>";for(size_t i=first;i<last;i++){Reminder r=reminderManager.getReminder(i);String cn=config.getChatName(r.chatId);if(!cn.length())cn=r.chatId;h+="<div class='card reminder "+String(r.enabled?"":"disabled")+"'><h3>"+esc(r.message)+"</h3><p><b>Chat:</b> "+esc(cn)+"</p><p><b>Schedule:</b> "+scheduleText(r)+"</p><p><b>Time:</b> "+p2(r.hour)+":"+p2(r.minute)+"</p><p><b>Notification:</b> "+String(r.silent?"Silent":"With sound")+"</p><div class='actions'><a class='button' href='/reminders/edit?id="+String(r.id)+"'>Edit</a><form method='POST' action='/reminders/clone'><input type='hidden' name='id' value='"+String(r.id)+"'><button class='secondary'>Clone</button></form><form method='POST' action='/reminders/toggle'><input type='hidden' name='id' value='"+String(r.id)+"'><input type='hidden' name='enabled' value='"+String(r.enabled?0:1)+"'><button class='secondary'>"+String(r.enabled?"Disable":"Enable")+"</button></form><form method='POST' action='/reminders/delete'><input type='hidden' name='id' value='"+String(r.id)+"'><button class='danger' onclick='return confirm(\"Delete this reminder?\")'>Delete</button></form></div></div>";}h+="<div class='pagination'>";if(page>1)h+="<a href='/reminders?page="+String(page-1)+"'>← Previous</a> ";h+="Page "+String(page)+" / "+String(pages);if(page<pages)h+=" <a href='/reminders?page="+String(page+1)+"'>Next →</a>";h+="</div></div><div class='card'><h2>Add reminder</h2><form method='POST' action='/reminders/add'>";Reminder blank;blank.type=ReminderType::ONCE;blank.month=1;blank.day=1;blank.year=2026;blank.hour=9;h+=reminderForm(blank,false)+"<button>Add reminder</button></form></div>";server.send(200,"text/html; charset=utf-8",h+getPageFooter());}
void WebServerManager::handleAddReminder(){Reminder r;if(!readReminder(server,r,false)){server.send(400,"text/plain","Invalid reminder data");return;}if(!reminderManager.addReminder(r)){server.send(500,"text/plain","Failed to create reminder");return;}server.sendHeader("Location","/reminders");server.send(303);}
void WebServerManager::handleEditReminder(){uint32_t id=server.arg("id").toInt();Reminder r;if(!id||!reminderManager.getReminderById(id,r)){server.send(404,"text/plain","Reminder not found");return;}String h=getPageHeader("Edit reminder")+getNavigation()+"<h1>Edit reminder</h1><div class='card'><form method='POST' action='/reminders/edit'>"+reminderForm(r,true)+"<button>Save reminder</button> <a class='button secondary' href='/reminders'>Cancel</a></form></div>";server.send(200,"text/html; charset=utf-8",h+getPageFooter());}
void WebServerManager::handleUpdateReminder(){uint32_t id=server.arg("id").toInt();Reminder r;if(!id||!reminderManager.getReminderById(id,r)){server.send(404,"text/plain","Reminder not found");return;}if(!readReminder(server,r,true)){server.send(400,"text/plain","Invalid reminder data");return;}if(!reminderManager.updateReminder(r)){server.send(500,"text/plain","Failed to update reminder");return;}server.sendHeader("Location","/reminders");server.send(303);}
void WebServerManager::handleCloneReminder(){uint32_t id=server.arg("id").toInt();Reminder r;if(!id||!reminderManager.getReminderById(id,r)){server.send(404,"text/plain","Reminder not found");return;}r.id=0;r.lastTriggered=0;r.nextTrigger=0;if(!reminderManager.addReminder(r)){server.send(500,"text/plain","Failed to clone reminder");return;}server.sendHeader("Location","/reminders");server.send(303);}
void WebServerManager::handleToggleReminder(){uint32_t id=server.arg("id").toInt();if(!reminderManager.setEnabled(id,server.arg("enabled").toInt()==1)){server.send(404,"text/plain","Reminder not found");return;}server.sendHeader("Location","/reminders");server.send(303);}
void WebServerManager::handleDeleteReminder(){uint32_t id=server.arg("id").toInt();if(!id||!reminderManager.deleteReminder(id)){server.send(404,"text/plain","Reminder not found");return;}server.sendHeader("Location","/reminders");server.send(303);}

void WebServerManager::handleHubTelegramSend(){String key=server.header("X-API-Key");if(!key.length())key=server.arg("apiKey");if(key!=config.getHubApiKey()){server.send(401,"application/json","{\"ok\":false,\"error\":\"Unauthorized\"}");return;}String chatId=server.arg("chatId"),message=server.arg("message");bool silent=server.arg("silent")=="1"||server.arg("silent")=="true";if(!chatId.length()&&config.getChatCount())chatId=config.getChat(0).id;if(!message.length()||!chatId.length()||!config.hasChat(chatId)){server.send(400,"application/json","{\"ok\":false,\"error\":\"Invalid request\"}");return;}bool ok=telegram.sendMessage(chatId,message,silent);server.send(ok?200:502,"application/json",ok?"{\"ok\":true}":"{\"ok\":false,\"error\":\"Telegram send failed\"}");}
void WebServerManager::handleNotFound(){server.send(404,"text/plain; charset=utf-8","404 - Not found");}

String WebServerManager::getPageHeader(const String& title){String h="<!DOCTYPE html><html lang='en'><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width, initial-scale=1'><title>"+esc(title)+"</title><style>";h+="*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f4f6f8;color:#222}.container{max-width:900px;margin:auto;padding:20px}nav{background:#222;padding:12px;border-radius:8px}nav a{color:#fff;text-decoration:none;margin-right:20px}.card{background:#fff;padding:20px;margin:20px 0;border-radius:8px;box-shadow:0 2px 5px rgba(0,0,0,.1)}label{display:block;margin-top:15px;font-weight:bold}input,textarea,select{width:100%;padding:10px;margin-top:5px;border:1px solid #ccc;border-radius:5px;font-size:16px}.checkbox{display:flex;align-items:center;gap:8px}.checkbox input{width:auto;margin:0}button,.button{display:inline-block;padding:10px 14px;font-size:16px;border:0;border-radius:5px;background:#333;color:#fff;text-decoration:none;cursor:pointer}.secondary{background:#666}.danger{background:#c0392b}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.actions form{margin:0}.disabled{opacity:.55}.item{padding:12px 0;border-bottom:1px solid #ddd}.pagination{text-align:center;margin-top:20px}.pagination a{margin:0 10px}.error{color:#c00}footer{text-align:center;color:#777;padding:20px 0;font-size:14px}@media(max-width:600px){.container{padding:12px}nav a{margin-right:10px;font-size:14px}}</style></head><body><div class='container'>";return h;}
String WebServerManager::getNavigation(){return "<nav><a href='/'>Home</a><a href='/settings'>Settings</a><a href='/reminders'>Reminders</a></nav>";}
String WebServerManager::getPageFooter(){return "<footer>"+esc(config.getDeviceName())+" Assistant</footer></div></body></html>";}
